import { AnimatePresence, motion } from "motion/react"
import { useState } from "react"

import { cn } from "@/lib/utils"

// Stand-in: motion + useState without "use client", palette classes throughout.
export const HoverEffect = ({
  items,
  className,
}: {
  items: { title: string; href: string }[]
  className?: string
}) => {
  const [active, setActive] = useState<number | null>(null)
  return (
    <div className={cn("grid gap-2 md:grid-cols-3", className)}>
      {items.map((item, i) => (
        <a key={item.href} href={item.href} className="relative block p-2" onMouseEnter={() => setActive(i)} onMouseLeave={() => setActive(null)}>
          <AnimatePresence>
            {active === i && <motion.span layoutId="highlight" className="absolute inset-0 rounded-xl bg-neutral-100 dark:bg-slate-800" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} />}
          </AnimatePresence>
          <div className="relative rounded-xl border border-neutral-200 bg-white p-4 dark:border-slate-700 dark:bg-black">
            <h4 className="font-medium text-zinc-900 dark:text-zinc-100">{item.title}</h4>
          </div>
        </a>
      ))}
    </div>
  )
}
